import type { Catalog } from './i18n';

/**
 * Spanish: every English text of the game (see i18n.ts) and its translation. Neutral Spanish
 * from Spain; the Host is addressed with "tú" everywhere, in the interface and in the voices.
 *
 * Names are never translated: the people (Nicole, Rask, Pim, Hedda Kroll, the pilots), the ships (Magpie,
 * Patience, Lot 7731, the Sovereign), the sponsors, their products and the places' proper names
 * (Psyche) stay as in English; a place named by a plain word (the Boneyard: der Schrottplatz, an arena's title)
 * is translated; a pun on a name is
 * explained beside it instead ("Magpie. Como la urraca: …").
 *
 * Glossary (one Spanish term per game term, kept in every text):
 * - Host: Host (an in-world title, kept; "el Host", plural "Hosts")
 * - clone: clon · pilot: piloto · callsign: indicativo
 * - Solar Coins: Solar Coins (the currency's name) · hangar: hangar
 * - Deathmatch: Todos contra todos · Race: Carrera · Last Clone Standing: El último clon en pie
 * - Capture the Flag: Captura la bandera · The President's Fleet: La flota del Presidente
 * - Orange / Blue (sides): Naranja / Azul · side: bando · sponsor core: núcleo (de patrocinador)
 * - flight school: Escuela de vuelo · course: curso · drill: ejercicio
 * - Basic training / Racer / Gladiator / Arsenal / Tactician: Entrenamiento básico / Piloto de carreras / Gladiador / Arsenal / Táctico
 * - overdrive: overdrive · hook: gancho · harpoon: arpón · winch: cabrestante · cable: cable
 * - torpedo: torpedo · probe: sonda · nova core: núcleo nova · twin laser: láser doble
 * - coil: bobina · gate: puerta · ring: anillo · lap: vuelta · racing line: trazada
 * - autopilot: piloto automático · free drift: deriva libre · flip: volteo (voltear) · dodge: esquiva
 * - battleship: acorazado · battery: batería · drive: motor · main drive: motor principal
 * - drive plume: chorro del motor · reactor: reactor
 * - armor (the hull's own): coraza · plating (upgrade and probe): blindaje
 * - thrusters: propulsores · radiators: radiadores · hull: casco · heat: calor
 * - neon trim: franjas de neón · drive flame: llama del motor · looks: estética
 * - aim / reflexes / daring: Puntería / Reflejos / Audacia · fine aim: puntería fina
 * - kill: baja · death: muerte · score: puntos · standings: clasificación · round: ronda
 * - live link: enlace en vivo · sponsor: patrocinador · ad: anuncio · kill cam: killcam
 * - solar flare: erupción solar (its shell: la esfera) · dogfight: duelo
 * - The Orange President: el Presidente Naranja · United Solar States: Estados Solares Unidos
 * - Ministry of War: Ministerio de la Guerra · Presidential Games: Juegos Presidenciales
 * - Rockborn: Rockborn (a faction's name, kept) · The Sovereign: la Sovereign (a ship's name, kept; the label alone: Sovereign)
 * - ping: Ping (the gamer term, kept)
 * - Nicole's pet names, one per English one: darling → cariño, love → mi amor, sweetheart → cielo,
 *   honey → corazón, my hero → mi héroe, big guy → grandullón, handsome → guapo.
 * - Ordinals: {n}.º for all four English endings.
 * - The announcer's lines stay lower case without ¿ ¡, as the English ones: the screen
 *   capitalizes the first letter of each sentence.
 */
